import { Panel, niceTicks } from '../plot.js';
import { venousReturnCurve, cardiacFunctionCurve } from '../../model/circulation.js';
import { cmH2OtoMmHg } from '../../model/units.js';

// The Guyton diagram. Both curves share right atrial pressure as their abscissa,
// so their intersection is the operating point. Intrathoracic pressure slides
// the cardiac function curve along that axis while leaving the venous return
// curve where it is — which is the entire mechanism by which a breath changes
// cardiac output.

/** Linear interpolation into a flat [x0,y0,x1,y1,…] curve. */
function valueAt(pts, x) {
 for (let i = 2; i < pts.length; i += 2) {
 const a = pts[i - 2], b = pts[i];
 if ((a <= x && x <= b) || (b <= x && x <= a)) {
 const t = (x - a) / ((b - a) || 1);
 return pts[i - 1] + t * (pts[i + 1] - pts[i - 1]);
 }
 }
 return NaN;
}

/**
 * Where the two curves cross — which is what the operating point of a Guyton
 * diagram *is*, and so where the marker has to sit.
 *
 * The alternative, plotting the model's own cycle-mean pressure and flow, leaves
 * the marker visibly off the curves. That gap is not a coding error: venous
 * return is a nonlinear function of right atrial pressure near the collapse
 * knee, and the mean of a nonlinear function is not that function of the mean.
 * Far from the knee the two agree to within 0.01 L/min; near it they differ by
 * about half a litre. The crossing is the honest thing to draw, and
 * docs/PHYSIOLOGY.md records how far the integrated model sits from it.
 */
function intersection(vr, cf) {
 const f = (x) => valueAt(vr, x) - valueAt(cf, x);
 let lo = Math.max(vr[0], cf[0]);
 let hi = Math.min(vr[vr.length - 2], cf[cf.length - 2]);
 if (!(f(lo) > 0) || !(f(hi) < 0)) return null; // no crossing in view
 for (let i = 0; i < 40; i++) {
 const mid = (lo + hi) / 2;
 if (f(mid) > 0) lo = mid; else hi = mid;
 }
 const x = (lo + hi) / 2;
 return { x, y: valueAt(vr, x) };
}

const TRAIL_INTERVAL = 0.025; // s of simulated time between trail samples
const TRAIL_POINTS = 480; // about 12 s of physiology

export function createGuyton(canvas) {
 const panel = new Panel(canvas, { padding: [22, 16, 34, 46] });
 const trail = []; // operating point over the last few seconds
 let lastSample = -1;

 function render(sim, colors) {
 panel.resize();
 const ctx = panel.begin();
 const { params: p, circ: c, metrics: m } = sim;

 // Everything on this plot is a cycle mean. Plotting the instantaneous right
 // atrial pressure against a beat-averaged output — which is what this used
 // to do — pairs two quantities measured over different windows, and sends
 // the marker skidding back and forth across a third of the axis at heart
 // rate while its height barely moves. The operating point of a Guyton
 // diagram is a mean pressure against a mean flow.
 const op = m.operatingPoint;
 const vr = venousReturnCurve(p, c, op);
 const cf = cardiacFunctionCurve(p, c, op);

 // Two different things, drawn as two different marks.
 //
 // `simulated` is where the integrated model actually is: the cycle-mean
 // right atrial pressure against the cycle-mean venous return. `equilibrium`
 // is where the graphical analysis says it should be — the crossing of the
 // two curves. They are close but not identical, because the cardiac
 // function curve is a single-beat approximation and because averaging a
 // nonlinear venous return relation over a cycle is not the same as
 // evaluating it at the mean pressure. Showing only the crossing, as this
 // panel used to, presents a derived equilibrium as if it were the patient.
 const simulated = { x: op.pra, y: op.flow };
 const equilibrium = intersection(vr.points, cf.points);

 // Sampled on simulated time so the trail covers a fixed span of physiology
 // regardless of frame rate, and stops growing when the model is paused.
 if (sim.time - lastSample >= TRAIL_INTERVAL) {
 lastSample = sim.time;
 trail.push(simulated.x, simulated.y);
 if (trail.length > TRAIL_POINTS * 2) trail.splice(0, 2);
 }

 const xLo = Math.min(-6, cf.xIntercept - 3, vr.pCrit - 3);
 const xHi = Math.max(vr.pmsf + 2, simulated.x + 6, 14);
 const yHi = Math.max(9, (vr.points[1] ?? 8) * 1.05, simulated.y * 1.6);
 panel.setDomain(xLo, xHi, 0, yHi);

 panel.grid(colors, {
 xTicks: niceTicks(xLo, xHi, 6), xFormat: (v) => v.toFixed(0),
 yTicks: niceTicks(0, yHi, 4), yFormat: (v) => v.toFixed(0),
 xLabel: 'Right atrial pressure (mmHg)',
 yLabel: 'Flow (L/min)',
 });
 panel.axisLine(colors, { y: 0 });

 panel.clip();

 // Pleural pressure marker: where the cardiac function curve is anchored.
 const pplMmHg = cmH2OtoMmHg(sim.resp.ppl);
 ctx.save();
 ctx.strokeStyle = colors.inkMuted;
 ctx.setLineDash([2, 3]);
 ctx.lineWidth = 1;
 ctx.beginPath();
 ctx.moveTo(panel.sx(pplMmHg), panel.sy(0));
 ctx.lineTo(panel.sx(pplMmHg), panel.sy(yHi));
 ctx.stroke();
 ctx.restore();

 // The loop the operating point walks over a breath.
 panel.line(trail, { color: colors.ink, width: 1.4, alpha: 0.3 });

 panel.line(vr.points, { color: colors.venous, width: 2 });
 panel.line(cf.points, { color: colors.arterial, width: 2 });

 panel.unclip();

 // Direct labels rather than a legend box.
 const vrLabelIdx = Math.floor(vr.points.length * 0.18) & ~1;
 panel.label('Venous return', vr.points[vrLabelIdx], vr.points[vrLabelIdx + 1], {
 color: colors.text.venous, dx: 6, dy: -10, halo: colors.surface,
 });
 const cfLabelIdx = Math.floor(cf.points.length * 0.82) & ~1;
 panel.label('Cardiac function', cf.points[cfLabelIdx], cf.points[cfLabelIdx + 1], {
 color: colors.text.arterial, dx: -6, dy: -10, align: 'right', halo: colors.surface,
 });

 panel.label(`Pmsf ${vr.pmsf.toFixed(1)}`, vr.pmsf, 0, {
 color: colors.text.venous, dx: -4, dy: -8, align: 'right', halo: colors.surface,
 });
 panel.label('Ppl', pplMmHg, yHi, {
 color: colors.inkMuted, dx: 4, dy: 12, halo: colors.surface,
 });

 // The analytic equilibrium: hollow, because it is a construction.
 if (equilibrium) {
 ctx.save();
 ctx.beginPath();
 ctx.arc(panel.sx(equilibrium.x), panel.sy(equilibrium.y), 5, 0, Math.PI * 2);
 ctx.strokeStyle = colors.ink;
 ctx.lineWidth = 1.6;
 ctx.globalAlpha = 0.55;
 ctx.stroke();
 ctx.restore();
 }
 // The simulated state: filled, because it is what the model is doing.
 panel.dot(simulated.x, simulated.y, { color: colors.ink, r: 4, ring: colors.surface });

 panel.label('simulated', simulated.x, simulated.y, {
 color: colors.ink, dx: 9, dy: 9, halo: colors.surface,
 });
 if (equilibrium && Math.abs(equilibrium.y - simulated.y) > yHi * 0.03) {
 panel.label('analytic', equilibrium.x, equilibrium.y, {
 color: colors.inkMuted, dx: 9, dy: -9, halo: colors.surface,
 });
 }

 panel.title('Guyton diagram', colors, 'where venous return meets cardiac function');
 }

 function clearTrail() { trail.length = 0; lastSample = -1; }

 return { render, clearTrail };
}

import { Simulator } from './model/simulator.js';
import { SCENARIOS, SCENARIO_BY_ID } from './model/scenarios.js';
import { theme } from './ui/theme.js';
import { createControls } from './ui/controls.js';
import { createStats } from './ui/stats.js';
import { createWaveforms } from './ui/panels/waveforms.js';
import { createGuyton } from './ui/panels/guyton.js';
import { createCampbell } from './ui/panels/campbell.js';
import { createPvLoops } from './ui/panels/pvloops.js';
import { createPvrCurve } from './ui/panels/pvrcurve.js';
import { createThorax } from './ui/panels/thorax.js';
import { createDescriptions } from './ui/descriptions.js';

theme.init();

const sim = new Simulator();

const el = (id) => document.getElementById(id);

const waveforms = createWaveforms(el('waveforms'));
const guyton = createGuyton(el('guyton'));
const campbell = createCampbell(el('campbell'));
const pvLoops = createPvLoops(el('pvloops'));
const pvrCurve = createPvrCurve(el('pvr'));
const thorax = createThorax(el('thorax'));
const stats = createStats(el('stats'), { banner: el('invalid-banner') });
const descriptions = createDescriptions();
const controls = createControls(el('controls'), sim, (id) => {
 if (id === 'mode') controls.sync();
 clearTrails();
 markCustom();
 dirty = true;
});

// ---------------------------------------------------------------- scenarios
const scenarioSelect = el('scenario');
const scenarioNote = el('scenario-note');
{
 const custom = document.createElement('option');
 custom.value = '';
 custom.textContent = 'Custom';
 scenarioSelect.appendChild(custom);
 for (const s of SCENARIOS) {
 const o = document.createElement('option');
 o.value = s.id;
 o.textContent = s.name;
 scenarioSelect.appendChild(o);
 }
}

function applyScenario(id) {
 const scenario = SCENARIO_BY_ID.get(id);
 if (!scenario) { scenarioNote.textContent = ''; return; }
 sim.applyScenario(scenario);
 sim.advance(20, true);
 controls.sync();
 clearTrails();
 dirty = true;
 scenarioNote.textContent = scenario.note;
}

scenarioSelect.addEventListener('change', () => applyScenario(scenarioSelect.value));

// Touching any control means the state is no longer the preset, so say so
// rather than leaving a scenario name attached to a patient it no longer
// describes.
function markCustom() {
 if (!scenarioSelect.value) return;
 scenarioSelect.value = '';
 scenarioNote.textContent = '';
}

function clearTrails() {
 guyton.clearTrail();
 campbell.clearTrail();
}

// ------------------------------------------------------------------ transport
let running = true;
let speed = 1;
let lastFrame = performance.now();

const playPause = el('playpause');
playPause.addEventListener('click', () => {
 running = !running;
 playPause.textContent = running ? 'Pause' : 'Play';
 playPause.classList.toggle('btn-primary', running);
 lastFrame = performance.now();
});

el('speed').addEventListener('change', (e) => { speed = parseFloat(e.target.value); });

el('reset').addEventListener('click', () => {
 const current = scenarioSelect.value;
 sim.reset();
 if (current) applyScenario(current); else controls.sync();
 clearTrails();
});

el('theme').addEventListener('click', (e) => {
 const mode = theme.cycle();
 e.currentTarget.title = `Colour theme: ${mode}`;
});

const sidebarToggle = el('sidebar-toggle');
sidebarToggle.addEventListener('click', () => {
 const open = document.body.classList.toggle('sidebar-open');
 sidebarToggle.setAttribute('aria-expanded', String(open));
});

// Space toggles the transport only when nothing interactive has focus. A native
// control must keep its own keyboard behaviour: with the old check, pressing
// space on Reset or the theme button toggled Play/Pause instead of activating
// the focused control.
document.addEventListener('keydown', (e) => {
 if (e.code !== 'Space' || e.metaKey || e.ctrlKey || e.altKey) return;
 const t = e.target;
 if (t instanceof Element && t.closest('button, input, select, textarea, a[href], [tabindex], summary, details')) return;
 e.preventDefault();
 playPause.click();
});

// ----------------------------------------------------------------- main loop
let statsClock = 0;

function draw() {
 const colors = theme.colors;
 waveforms.render(sim, colors);
 guyton.render(sim, colors);
 campbell.render(sim, colors);
 pvLoops.render(sim, colors);
 pvrCurve.render(sim, colors);
 thorax.render(sim, colors);
 stats.render(sim.metrics);
 descriptions.render(sim);
 dirty = false;
}

// Anything that changes what should be on screen without the model advancing.
let dirty = true;
export function invalidate() { dirty = true; }
theme.onChange(() => { dirty = true; });
new ResizeObserver(() => { dirty = true; }).observe(document.body);

function frame(now) {
 const dtWall = Math.min((now - lastFrame) / 1000, 0.1);
 lastFrame = now;

 if (running) {
 sim.advance(dtWall * speed);
 dirty = true;
 }

 // Paused and unchanged: nothing to redraw. The canvases hold their last
 // frame, so this is free rather than blank.
 if (dirty) {
 const colors = theme.colors;
 waveforms.render(sim, colors);
 guyton.render(sim, colors);
 campbell.render(sim, colors);
 pvLoops.render(sim, colors);
 pvrCurve.render(sim, colors);
 thorax.render(sim, colors);

 statsClock += dtWall;
 if (statsClock > 0.12 || !running) {
 stats.render(sim.metrics);
 descriptions.render(sim);
 statsClock = 0;
 }
 if (!running) dirty = false;
 }

 requestAnimationFrame(frame);
}

// A backgrounded tab stops firing animation frames; without this the first
// frame after returning would be timed from whenever the tab was hidden.
document.addEventListener('visibilitychange', () => { lastFrame = performance.now(); });

// Handle for scripting the simulator from the console or an embedding page.
window.heartLung = {
 sim,
 draw,
 /** Advance the model by `seconds` of simulated time and repaint. */
 step(seconds = 1) { sim.advance(seconds); draw(); return sim.metrics; },
};

scenarioSelect.value = 'healthy-vcv';
applyScenario('healthy-vcv');
requestAnimationFrame(frame);

// Minimal cartesian canvas plotting: device-pixel-ratio handling, linear scales,
// a recessive grid, and the mark specs the panels share. No dependencies.

export class Panel {
 constructor(canvas, { padding = [12, 14, 26, 44] } = {}) {
 this.canvas = canvas;
 this.ctx = canvas.getContext('2d');
 this.padding = padding; // top, right, bottom, left, in CSS pixels
 this.dpr = 1;
 this.w = 0;
 this.h = 0;
 this.domain = { x0: 0, x1: 1, y0: 0, y1: 1 };
 this.resize();
 }

 resize() {
 const rect = this.canvas.getBoundingClientRect();
 const dpr = window.devicePixelRatio || 1;
 // Belt and braces against the layout feedback loop the CSS also guards
 // against: whatever happens, never allocate a backing store larger than a
 // screen's worth of pixels.
 const cap = 4096 / dpr;
 const w = Math.max(1, Math.min(cap, Math.round(rect.width)));
 const h = Math.max(1, Math.min(cap, Math.round(rect.height)));
 if (w === this.w && h === this.h && dpr === this.dpr) return false;
 this.w = w; this.h = h; this.dpr = dpr;
 this.canvas.width = Math.round(w * dpr);
 this.canvas.height = Math.round(h * dpr);
 return true;
 }

 get plotArea() {
 const [t, r, b, l] = this.padding;
 return { x: l, y: t, w: Math.max(1, this.w - l - r), h: Math.max(1, this.h - t - b) };
 }

 begin() {
 const { ctx } = this;
 ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
 ctx.clearRect(0, 0, this.w, this.h);
 ctx.lineJoin = 'round';
 ctx.lineCap = 'round';
 ctx.font = '11px system-ui, -apple-system, "Segoe UI", sans-serif';
 return ctx;
 }

 setDomain(x0, x1, y0, y1) { this.domain = { x0, x1, y0, y1 }; }

 sx(v) {
 const a = this.plotArea, d = this.domain;
 return a.x + ((v - d.x0) / (d.x1 - d.x0 || 1)) * a.w;
 }

 sy(v) {
 const a = this.plotArea, d = this.domain;
 return a.y + a.h - ((v - d.y0) / (d.y1 - d.y0 || 1)) * a.h;
 }

 clip() {
 const a = this.plotArea;
 this.ctx.save();
 this.ctx.beginPath();
 this.ctx.rect(a.x, a.y, a.w, a.h);
 this.ctx.clip();
 }

 unclip() { this.ctx.restore(); }

 /** Recessive grid plus axis labels. `ticks` are arrays of domain values. */
 grid(colors, { xTicks = [], yTicks = [], xFormat, yFormat, yLabel, xLabel } = {}) {
 const { ctx } = this, a = this.plotArea;
 ctx.save();
 ctx.strokeStyle = colors.grid;
 ctx.lineWidth = 1;
 ctx.fillStyle = colors.inkMuted;
 ctx.font = '10px system-ui, -apple-system, "Segoe UI", sans-serif';

 for (const t of yTicks) {
 const y = Math.round(this.sy(t)) + 0.5;
 if (y < a.y - 1 || y > a.y + a.h + 1) continue;
 ctx.beginPath(); ctx.moveTo(a.x, y); ctx.lineTo(a.x + a.w, y); ctx.stroke();
 if (yFormat) {
 ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
 ctx.fillText(yFormat(t), a.x - 6, y);
 }
 }
 for (const t of xTicks) {
 const x = Math.round(this.sx(t)) + 0.5;
 if (x < a.x - 1 || x > a.x + a.w + 1) continue;
 ctx.beginPath(); ctx.moveTo(x, a.y); ctx.lineTo(x, a.y + a.h); ctx.stroke();
 if (xFormat) {
 ctx.textAlign = 'center'; ctx.textBaseline = 'top';
 ctx.fillText(xFormat(t), x, a.y + a.h + 5);
 }
 }
 if (yLabel) {
 ctx.save();
 ctx.translate(10, a.y + a.h / 2);
 ctx.rotate(-Math.PI / 2);
 ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
 ctx.fillStyle = colors.inkMuted;
 ctx.fillText(yLabel, 0, 0);
 ctx.restore();
 }
 if (xLabel) {
 ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
 ctx.fillStyle = colors.inkMuted;
 ctx.fillText(xLabel, a.x + a.w / 2, this.h - 1);
 }
 ctx.restore();
 }

 axisLine(colors, { x = null, y = null } = {}) {
 const { ctx } = this, a = this.plotArea;
 ctx.save();
 ctx.strokeStyle = colors.axis;
 ctx.lineWidth = 1;
 ctx.beginPath();
 if (y !== null) { const yy = Math.round(this.sy(y)) + 0.5; ctx.moveTo(a.x, yy); ctx.lineTo(a.x + a.w, yy); }
 if (x !== null) { const xx = Math.round(this.sx(x)) + 0.5; ctx.moveTo(xx, a.y); ctx.lineTo(xx, a.y + a.h); }
 ctx.stroke();
 ctx.restore();
 }

 /** `pts` is a flat [x0,y0,x1,y1,…] array in domain units. */
 line(pts, { color, width = 2, dash = null, alpha = 1, count = pts.length } = {}) {
 if (count < 4) return;
 const { ctx } = this;
 ctx.save();
 ctx.globalAlpha = alpha;
 ctx.strokeStyle = color;
 ctx.lineWidth = width;
 if (dash) ctx.setLineDash(dash);
 ctx.beginPath();
 ctx.moveTo(this.sx(pts[0]), this.sy(pts[1]));
 for (let i = 2; i < count; i += 2) ctx.lineTo(this.sx(pts[i]), this.sy(pts[i + 1]));
 ctx.stroke();
 ctx.restore();
 }

 /**
 * Series where x is implied by index over the domain, for trace buffers.
 * Decimated to roughly two points per pixel — beyond that the extra segments
 * cost time and change nothing on screen. Each decimated column keeps both
 * its minimum and maximum so spikes survive.
 */
 series(data, n, x0, x1, { color, width = 1.75, alpha = 1 }) {
 if (n < 2) return;
 const { ctx } = this;
 const a = this.plotArea;
 ctx.save();
 ctx.globalAlpha = alpha;
 ctx.strokeStyle = color;
 ctx.lineWidth = width;
 ctx.beginPath();
 const step = a.w / (n - 1);
 const bucket = Math.max(1, Math.floor(n / (a.w * 2)));
 if (bucket === 1) {
 ctx.moveTo(a.x, this.sy(data[0]));
 for (let i = 1; i < n; i++) ctx.lineTo(a.x + i * step, this.sy(data[i]));
 } else {
 let started = false;
 for (let i = 0; i < n; i += bucket) {
 let lo = data[i], hi = data[i];
 const end = Math.min(i + bucket, n);
 for (let k = i + 1; k < end; k++) {
 if (data[k] < lo) lo = data[k];
 if (data[k] > hi) hi = data[k];
 }
 const x = a.x + i * step;
 if (!started) { ctx.moveTo(x, this.sy(lo)); started = true; }
 ctx.lineTo(x, this.sy(lo));
 ctx.lineTo(x, this.sy(hi));
 }
 }
 ctx.stroke();
 ctx.restore();
 }

 dot(x, y, { color, r = 4.5, ring = null }) {
 const { ctx } = this;
 ctx.save();
 if (ring) {
 ctx.beginPath();
 ctx.arc(this.sx(x), this.sy(y), r + 2, 0, Math.PI * 2);
 ctx.fillStyle = ring;
 ctx.fill();
 }
 ctx.beginPath();
 ctx.arc(this.sx(x), this.sy(y), r, 0, Math.PI * 2);
 ctx.fillStyle = color;
 ctx.fill();
 ctx.restore();
 }

 band(x0, x1, colors, alpha = 0.07) {
 const { ctx } = this, a = this.plotArea;
 ctx.save();
 ctx.globalAlpha = alpha;
 ctx.fillStyle = colors.ink;
 ctx.fillRect(this.sx(x0), a.y, this.sx(x1) - this.sx(x0), a.h);
 ctx.restore();
 }

 /**
 * Direct label anchored to a point. Every series carries one — it is the
 * secondary encoding that keeps hue from being the only channel.
 */
 label(text, x, y, { color, align = 'left', baseline = 'middle', dx = 6, dy = 0, halo }) {
 const { ctx } = this;
 ctx.save();
 ctx.font = '600 11px system-ui, -apple-system, "Segoe UI", sans-serif';
 ctx.textAlign = align;
 ctx.textBaseline = baseline;
 const px = this.sx(x) + dx, py = this.sy(y) + dy;
 if (halo) {
 ctx.lineWidth = 3.5;
 ctx.strokeStyle = halo;
 ctx.strokeText(text, px, py);
 }
 ctx.fillStyle = color;
 ctx.fillText(text, px, py);
 ctx.restore();
 }

 /**
 * Panel heading, with the subtitle dropped rather than clipped when the panel
 * is too narrow for both. A half-written label reads as a rendering fault.
 */
 title(text, colors, sub) {
 const { ctx } = this;
 ctx.save();
 ctx.textAlign = 'left';
 ctx.textBaseline = 'top';
 ctx.font = '600 12px system-ui, -apple-system, "Segoe UI", sans-serif';
 ctx.fillStyle = colors.ink;
 ctx.fillText(text, 4, 2);
 if (sub) {
 const titleWidth = ctx.measureText(text).width;
 ctx.font = '11px system-ui, -apple-system, "Segoe UI", sans-serif';
 const x = 4 + titleWidth + 8;
 if (x + ctx.measureText(sub).width <= this.w - 4) {
 ctx.fillStyle = colors.inkMuted;
 ctx.fillText(sub, x, 3);
 }
 }
 ctx.restore();
 }
}

export function niceTicks(lo, hi, target = 5) {
 const span = hi - lo;
 if (!(span > 0)) return [lo];
 const raw = span / target;
 const mag = Math.pow(10, Math.floor(Math.log10(raw)));
 const norm = raw / mag;
 const step = (norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10) * mag;
 const out = [];
 for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-6; v += step) {
 out.push(Math.abs(v) < step * 1e-6 ? 0 : v);
 }
 return out;
}

// A closed-loop lumped-parameter circulation. Eight compliant compartments, all
// volumes conserved, with each compartment referenced to the pressure that
// actually surrounds it:
//
// systemic arteries -> atmosphere
// systemic veins -> abdominal pressure
// RA, RV, LA, LV -> pleural pressure + pericardial pressure
// PA, PV -> pleural pressure
//
// Nothing about heart-lung interaction is added on top of this; it all falls out
// of that table. Raising intrathoracic pressure lifts right atrial pressure but
// not the systemic venous reservoir, so venous return falls. It lifts left
// ventricular cavity pressure and aortic pressure is unchanged, so the LV
// unloads. It lifts the RV and the pulmonary artery equally, so RV afterload is
// untouched — only lung volume can move that.

import { cmH2OtoMmHg, clamp } from './units.js';
import { pvrAt } from './respiratory.js';

// Unstressed volumes (mL) and compliances (mL/mmHg) that are not user-facing.
export const VASC = {
 vuSa: 700, cSa: 1.35,
 vuSv: 2800,
 vuPa: 90, cPa: 4.2,
 vuPv: 180, cPv: 8.5,
 rPulVen: 0.008,
};

const VALVE = { tricuspid: 0.004, pulmonic: 0.004, mitral: 0.005, aortic: 0.006 };

// Ventricular and atrial elastance descriptors.
export const CHAMBER = {
 lv: { v0s: 15, v0d: 10, edA: 0.45 },
 rv: { v0s: 10, v0d: 10, edA: 0.32, edB: 0.021 },
 ra: { v0: 8, eMin: 0.072, eMax: 0.20 },
 la: { v0: 10, eMin: 0.135, eMax: 0.30 },
};

const PERI = { v0: 430, scale: 62, k: 0.55 };
// Only the splanchnic share of the venous reservoir sits inside the abdomen;
// limb and cervical veins see atmosphere, so abdominal pressure is transmitted
// to mean systemic filling pressure at less than unity.
const ABD_VENOUS_FRACTION = 0.6;
const SEPTAL = { rvToLv: 0.085, lvToRv: 0.014, rvRef: 145, lvRef: 135, systolic: 0.042 };

export function createCirculationState(p) {
 return {
 vSa: 830,
 vSv: VASC.vuSv + p.stressedVolume,
 vRa: 55,
 vRv: 130,
 vPa: 140,
 vPv: 235,
 vLa: 72,
 vLv: 118,
 tCardiac: 0,
 // Per-beat trackers
 lvEdv: 122, lvEsv: 52, rvEdv: 132, rvEsv: 62,
 lvEsvRun: 1e9, rvEsvRun: 1e9,
 lvEsp: 100, rvEsp: 25,
 sv: 70, co: 5.2,
 beatCount: 0,
 limitTicks: 0,
 lastLoopLv: [], lastLoopRv: [], loopLv: [], loopRv: [],
 };
}

// Double-hill ventricular activation, normalised to a peak of 1.
function ventricularActivation(tn) {
 const a1 = 0.28, n1 = 1.9, a2 = 0.46, n2 = 18;
 const g1 = Math.pow(tn / a1, n1);
 const g2 = Math.pow(tn / a2, n2);
 return (g1 / (1 + g1)) * (1 / (1 + g2)) / 0.885;
}

// Atrial systole occupies the last fifth of the cardiac cycle.
function atrialActivation(tn) {
 const start = 0.80;
 if (tn < start) return 0;
 return Math.sin((Math.PI * (tn - start)) / (1 - start)) ** 2;
}

function ventricularPressure(v, act, ees, v0s, edA, edB, v0d) {
 const passive = edA * (Math.exp(edB * Math.max(0, v - v0d)) - 1);
 const active = ees * (v - v0s);
 return act * active + (1 - act) * passive;
}

function valveFlow(pUp, pDown, r) {
 const dp = pUp - pDown;
 return dp > 0 ? dp / r : 0;
}

// Which compartment each flow drains, and which it fills, when the flow is
// positive. Two of them (systemic capillary and pulmonary venous) can reverse,
// so the source is decided by sign at the time.
const FLOW_EDGES = [
 ['av', 'vLv', 'vSa'], ['sys', 'vSa', 'vSv'], ['vr', 'vSv', 'vRa'], ['tv', 'vRa', 'vRv'],
 ['pv', 'vRv', 'vPa'], ['pul', 'vPa', 'vPv'], ['pulVen', 'vPv', 'vLa'], ['mv', 'vLa', 'vLv'],
];
const VOLUME_FLOOR = 1; // mL a compartment may never be drained below

// Collapse of the great veins is progressive rather than a hard knee: as right
// atrial pressure approaches the closing pressure the vessel flutters, so
// sensitivity to Pra fades over roughly a millimetre of mercury instead of
// vanishing at a point.
const COLLAPSE_KNEE = 1.1; // mmHg

/**
 * Venous return, in mL/s. The single definition — the integrator and the curve
 * drawn on the Guyton diagram both call this, so the plot cannot drift away
 * from the model the way it did when the curve used a hard `max()` against a
 * softplus in the integrator.
 */
export function venousReturnBackPressure(pra, pCrit) {
 return pCrit + COLLAPSE_KNEE * Math.log1p(Math.exp((pra - pCrit) / COLLAPSE_KNEE));
}

export function venousReturnFlow(pmsf, pra, pCrit, rvr) {
 return Math.max(0, (pmsf - venousReturnBackPressure(pra, pCrit)) / rvr);
}

/**
 * Scale back any flow that would drain its source compartment past the floor.
 * Mutates `q` and returns true if anything was limited — which is the signal
 * that the model has been driven outside the range where its equations mean
 * anything, and that the readouts should say so rather than report a number.
 */
function limitFlows(c, q, dt) {
 let demand = null;
 for (const [key, from, to] of FLOW_EDGES) {
 const f = q[key];
 if (f === 0) continue;
 const src = f > 0 ? from : to;
 (demand ??= {})[src] = (demand[src] ?? 0) + Math.abs(f);
 }
 if (!demand) return false;

 let scale = null;
 for (const name in demand) {
 const wanted = demand[name] * dt;
 const available = Math.max(0, c[name] - VOLUME_FLOOR);
 if (wanted > available) (scale ??= {})[name] = available / wanted;
 }
 if (!scale) return false;

 for (const [key, from, to] of FLOW_EDGES) {
 const f = q[key];
 if (f === 0) continue;
 const s = scale[f > 0 ? from : to];
 if (s !== undefined) q[key] = f * s;
 }
 return true;
}

/**
 * Advance the circulation by dt seconds.
 * `resp` supplies ppl / palv / pab in cmH2O and lungVolume in litres.
 */
export function stepCirculation(p, c, resp, dt) {
 const period = 60 / p.hr;
 c.tCardiac += dt;
 if (c.tCardiac >= period) {
 c.tCardiac -= period;
 closeBeat(c);
 }
 const tn = c.tCardiac / period;
 const actV = ventricularActivation(tn);
 const actA = atrialActivation(tn);

 const ppl = cmH2OtoMmHg(resp.ppl);
 const palv = cmH2OtoMmHg(resp.palv);
 const pab = cmH2OtoMmHg(resp.pab);
 const vAboveFrc = resp.lungVolume - p.frc;

 // --- pericardium: the four chambers share one space ----------------------
 const vHeart = c.vRa + c.vRv + c.vLa + c.vLv;
 const pPeri = p.pericardium > 0 && vHeart > PERI.v0
 ? p.pericardium * PERI.k * (Math.exp((vHeart - PERI.v0) / PERI.scale) - 1)
 : 0;
 const pExtCardiac = ppl + pPeri;

 // --- chamber transmural pressures ---------------------------------------
 const septalToLv = p.septal * SEPTAL.rvToLv * Math.max(0, c.vRv - SEPTAL.rvRef);
 const septalToRv = p.septal * SEPTAL.lvToRv * Math.max(0, c.vLv - SEPTAL.lvRef);

 let pLvTm = ventricularPressure(c.vLv, actV, p.eesLv, CHAMBER.lv.v0s,
 CHAMBER.lv.edA, p.lvStiff, CHAMBER.lv.v0d) + septalToLv;
 // Systolic interdependence: a large share of RV systolic pressure is generated
 // by the contracting left ventricle through shared myofibres. This is anatomy
 // rather than septal geometry, so it is not on the septal-coupling control —
 // that control isolates the diastolic septal shift.
 const lvAssist = SEPTAL.systolic * actV * p.eesLv * Math.max(0, c.vLv - CHAMBER.lv.v0s);
 let pRvTm = ventricularPressure(c.vRv, actV, p.eesRv, CHAMBER.rv.v0s,
 CHAMBER.rv.edA, CHAMBER.rv.edB, CHAMBER.rv.v0d) + septalToRv + lvAssist;

 const eRa = CHAMBER.ra.eMin + (CHAMBER.ra.eMax - CHAMBER.ra.eMin) * actA;
 const eLa = CHAMBER.la.eMin + (CHAMBER.la.eMax - CHAMBER.la.eMin) * actA;
 const pRaTm = eRa * (c.vRa - CHAMBER.ra.v0);
 const pLaTm = eLa * (c.vLa - CHAMBER.la.v0);

 const pRa = pRaTm + pExtCardiac;
 const pRv = pRvTm + pExtCardiac;
 const pLa = pLaTm + pExtCardiac;
 const pLv = pLvTm + pExtCardiac;

 // --- vascular compartments ----------------------------------------------
 const pSa = (c.vSa - VASC.vuSa) / VASC.cSa;
 // The splanchnic reservoir is surrounded by abdominal pressure, but what that
 // pressure does depends on how full the bed is. With a distended abdominal
 // venous compartment (zone III) diaphragmatic descent squeezes blood forward
 // and raises mean systemic filling pressure. With a collapsed one (zone I/II)
 // the same pressure obliterates the capacitance vessels instead, raising the
 // resistance to venous return rather than the pressure head.
 const pmsfElastic = (c.vSv - VASC.vuSv) / p.csv;
 const abdZone = clamp((pmsfElastic - 2) / 8, 0, 1);
 const pmsf = pmsfElastic + ABD_VENOUS_FRACTION * pab * abdZone;
 const rvrEff = p.rvr * (1 + 0.5 * (1 - abdZone) * Math.max(0, pab - 2) / 4);
 const pPa = (c.vPa - VASC.vuPa) / VASC.cPa + ppl;

 // Lung inflation squeezes the pulmonary vascular bed toward the left atrium,
 // but only where the capillaries are open (zone III).
 const pPvRaw = (c.vPv - VASC.vuPv) / VASC.cPv + ppl;
 const zone3 = clamp((pPvRaw - palv) / 4, 0, 1);
 const vuPvEff = VASC.vuPv - p.piston * Math.max(0, vAboveFrc) * zone3;
 const pPv = (c.vPv - vuPvEff) / VASC.cPv + ppl;

 // --- flows ---------------------------------------------------------------
 // Venous return with a Starling resistor: once right atrial pressure falls
 // below the pressure surrounding the great veins, the vessel flutters shut and
 // flow stops rising. This is the plateau of the venous return curve. The IVC
 // tolerates roughly 5 cmH2O of transmural compression before it collapses.
 const pCrit = pab - cmH2OtoMmHg(5);
 const qVr = venousReturnFlow(pmsf, pRa, pCrit, rvrEff);
 const qSys = (pSa - pmsf) / p.svr;

 const pvr = pvrAt(p, resp.lungVolume);
 // Vascular waterfall: where alveolar pressure exceeds pulmonary venous
 // pressure, alveolar pressure — not left atrial pressure — is the downstream
 // pressure for flow.
 const qPul = Math.max(0, (pPa - Math.max(pPv, palv)) / pvr);
 const qPulVen = (pPv - pLa) / VASC.rPulVen;

 const qTv = valveFlow(pRa, pRv, VALVE.tricuspid);
 const qPv = valveFlow(pRv, pPa, VALVE.pulmonic);
 const qMv = valveFlow(pLa, pLv, VALVE.mitral);
 const qAv = valveFlow(pLv, pSa, VALVE.aortic);

 // A compartment cannot give up volume it does not have. Without this a large
 // adverse gradient across the unvalved pulmonary venous connection empties the
 // left atrium straight through zero — a randomised sweep of the control ranges
 // reached −128 mL. Scaling both ends of a flow by the same factor keeps total
 // volume conserved exactly.
 const q = { av: qAv, sys: qSys, vr: qVr, tv: qTv, pv: qPv, pul: qPul, pulVen: qPulVen, mv: qMv };
 const limited = limitFlows(c, q, dt);

 // --- integrate -----------------------------------------------------------
 c.vSa += (q.av - q.sys) * dt;
 c.vSv += (q.sys - q.vr) * dt;
 c.vRa += (q.vr - q.tv) * dt;
 c.vRv += (q.tv - q.pv) * dt;
 c.vPa += (q.pv - q.pul) * dt;
 c.vPv += (q.pul - q.pulVen) * dt;
 c.vLa += (q.pulVen - q.mv) * dt;
 c.vLv += (q.mv - q.av) * dt;

 // --- expose the instantaneous state --------------------------------------
 c.p = {
 ra: pRa, rv: pRv, la: pLa, lv: pLv, sa: pSa, pa: pPa, pv: pPv,
 pmsf, pCrit, pPeri, ppl, palv, pab, rvrEff, abdZone,
 raTm: pRaTm, rvTm: pRvTm, lvTm: pLvTm, laTm: pLaTm,
 zone3, pvr, vHeart,
 };
 c.q = { vr: q.vr, sys: q.sys, pul: q.pul, tv: q.tv, pv: q.pv, mv: q.mv, av: q.av, pulVen: q.pulVen };
 c.act = { v: actV, a: actA, tn };

 // Latch the fact that limiting happened so it survives to the next readout,
 // and decay it so the state clears once the model returns to a sane regime.
 if (limited) c.limitTicks = 4000; // about a second of simulated time at the default step
 else if (c.limitTicks > 0) c.limitTicks--;

 // End-systolic volume of the beat currently in progress. End-diastolic volume
 // is read at the beat boundary itself rather than as a maximum over the
 // window, which would otherwise pair one beat's ESV with the next beat's EDV
 // and smooth away the respiratory variation we are trying to show.
 c.lvEsvRun = Math.min(c.lvEsvRun, c.vLv);
 c.rvEsvRun = Math.min(c.rvEsvRun, c.vRv);
 // Stored transmural. Two consumers used to correct these themselves and did
 // it differently: the pressure–volume loops subtracted pleural pressure only,
 // the cardiac function curve subtracted a pleural pressure from a different
 // instant than the beat the pressure came from.
 if (q.av > 0) c.lvEspRun = pLvTm;
 if (q.pv > 0) c.rvEspRun = pRvTm;

 // Pressure-volume loop trace, subsampled.
 if (!c._loopTick) c._loopTick = 0;
 if (c._loopTick++ % 8 === 0) {
 c.loopLv.push(c.vLv, pLvTm);
 c.loopRv.push(c.vRv, pRvTm);
 if (c.loopLv.length > 1200) c.loopLv.splice(0, 400);
 if (c.loopRv.length > 1200) c.loopRv.splice(0, 400);
 }

 return c;
}

function closeBeat(c) {
 // Sampled at end-diastole, before this step's pressures are recomputed. The
 // clinically meaningful septal shift is a diastolic finding — taking the
 // instantaneous difference instead would just track the cardiac cycle, since
 // left ventricular pressure dominates through the whole of systole.
 if (c.p) c.septalShift = c.p.rvTm - c.p.lvTm;

 // Volume at this instant is end-diastolic: the beat that just finished began
 // from `edvPending` and reached `lvEsvRun`.
 if (c.edvPending !== undefined) {
 c.lvEdv = c.edvPending; c.lvEsv = c.lvEsvRun;
 c.rvEdv = c.rvEdvPending; c.rvEsv = c.rvEsvRun;
 c.sv = Math.max(0, c.lvEdv - c.lvEsv);
 c.svRv = Math.max(0, c.rvEdv - c.rvEsv);
 }
 c.edvPending = c.vLv;
 c.rvEdvPending = c.vRv;
 c.lvEsp = c.lvEspRun ?? c.lvEsp;
 c.rvEsp = c.rvEspRun ?? c.rvEsp;
 c.lvEsvRun = 1e9; c.rvEsvRun = 1e9;
 c.beatCount++;
 c.lastLoopLv = c.loopLv; c.loopLv = [];
 c.lastLoopRv = c.loopRv; c.loopRv = [];
}

// ---------------------------------------------------------------------------
// Curves derived from the live parameters, for the Guyton diagram. These are
// computed from the same constants the integrator uses, so the intersection of
// the two curves lands on the operating point the simulation actually reaches.
// ---------------------------------------------------------------------------

/**
 * Venous return as a function of right atrial pressure, in L/min.
 * `mean` carries the cycle-averaged state, so the curve is not redrawn several
 * times a second by the cardiac ripple riding on these pressures.
 */
export function venousReturnCurve(p, c, mean, nPoints = 90) {
 const pmsf = mean?.pmsf ?? c.p.pmsf;
 const pCrit = mean?.pCrit ?? c.p.pCrit; // follows lung volume, so it moves with the breath
 const pts = [];
 const lo = Math.min(pCrit - 6, -6);
 for (let i = 0; i < nPoints; i++) {
 const pra = lo + ((pmsf + 3 - lo) * i) / (nPoints - 1);
 const q = venousReturnFlow(pmsf, pra, pCrit, c.p.rvrEff);
 pts.push(pra, (q * 60) / 1000);
 }
 return { points: pts, pmsf, pCrit };
}

/**
 * Right ventricular function as a function of right atrial pressure, in L/min.
 * Filling pressure is converted to transmural pressure, inverted through the RV
 * EDPVR to an end-diastolic volume, then run through the single-beat
 * elastance relation with the arterial elastance the RV currently faces.
 */
export function cardiacFunctionCurve(p, c, mean, nPoints = 90) {
 // Both terms are cycle-averaged. Sliding this curve along the pressure axis
 // with each breath is the phenomenon the diagram exists to show, and averaging
 // over one cardiac cycle leaves the respiratory swing intact while removing
 // the beat-to-beat ripple that would otherwise jitter the intercept.
 const pExt = (mean?.ppl ?? c.p.ppl) + (mean?.pPeri ?? c.p.pPeri);
 const svRv = Math.max(4, c.svRv ?? c.sv);
 const ea = Math.max(0.02, c.rvEsp / svRv); // both transmural, same beat
 const { edA, edB, v0d, v0s } = { ...CHAMBER.rv, v0s: CHAMBER.rv.v0s };
 const pts = [];
 for (let i = 0; i < nPoints; i++) {
 const pra = pExt - 4 + (i * 22) / (nPoints - 1);
 const ptm = pra - pExt;
 // Invert the exponential EDPVR.
 const edv = ptm <= 0 ? v0d : v0d + Math.log(ptm / edA + 1) / edB;
 const sv = Math.max(0, (p.eesRv * (edv - v0s)) / (p.eesRv + ea));
 pts.push(pra, (sv * p.hr) / 1000);
 }
 return { points: pts, xIntercept: pExt };
}

// Respiratory mechanics, built on the equation of motion and split into the two
// series elements the Campbell diagram draws separately: the lung and the chest
// wall. Volumes are litres above the relaxation volume (FRC); pressures cmH2O.
//
// Palv = V / Crs - Pmus
// Ppl = PPL_FRC + V / Ccw - Pmus
// flow = (Pao - Palv) / Raw
//
// Pleural pressure therefore follows the chest wall compliance curve while
// alveolar pressure follows the respiratory system curve — the distinction that
// makes airway pressure a poor proxy for the pressure the heart actually feels.

import { clamp } from './units.js';

// Pleural pressure at the relaxation volume. Its negative is the
// transpulmonary recoil at FRC, which is why alveolar pressure there is zero.
export const PPL_FRC = -5; // cmH2O

export function createRespiratoryState() {
 return {
 v: 0, // L above relaxation volume
 flow: 0, // L/s, positive = inspiratory
 phase: 'exp',
 tCycle: 0,
 tPhase: 0,
 pmus: 0,
 prevPhase: 'exp',
 canTrigger: true,
 breathCount: 0,
 peakInspFlow: 0,
 // Latched once per breath for the readouts.
 lastPplat: 0,
 lastPpeak: 0,
 lastVt: 0,
 lastAutoPeep: 0,
 lastPplSwing: 0,
 pplatCandidate: 0,
 pplMin: Infinity,
 pplMax: -Infinity,
 vtAccum: 0,
 ppeakAccum: -Infinity,
 };
}

export function respiratorySystemCompliance(p) {
 return 1 / (1 / p.clung + 1 / p.ccw);
}

// How long the inspiratory muscles are active. Capped at half the respiratory
// cycle so effort never runs into the next breath.
function neuralInspiratoryTime(p, period) {
 return Math.min(p.ti, period * 0.5);
}

// Inspiratory muscle pressure: one continuous rise-and-release over the neural
// inspiratory time, zero in a fully passive patient. It has to reach zero at
// both ends — a discontinuity here would make the phase detector chatter.
function musclePressure(p, tCycle, period) {
 if (p.pmus <= 0) return 0;
 const tNeural = neuralInspiratoryTime(p, period);
 if (tCycle >= tNeural) return 0;
 return p.pmus * Math.sin((Math.PI * tCycle) / tNeural) ** 1.2;
}

// Airway opening pressure applied by the ventilator for the current phase.
function airwayOpeningPressure(p, r, period) {
 switch (p.mode) {
 case 'spont':
 return p.peep; // CPAP level; zero means an unsupported breath
 case 'vcv':
 return null; // flow is imposed instead
 case 'pcv':
 return r.phase === 'insp' ? p.peep + p.pinsp : p.peep;
 case 'psv':
 return r.phase === 'insp' ? p.peep + p.pinsp : p.peep;
 default:
 return p.peep;
 }
}

export function stepRespiratory(p, r, dt) {
 const period = 60 / p.rr;
 const crs = respiratorySystemCompliance(p) / 1000; // L/cmH2O
 const ccw = p.ccw / 1000;

 r.tCycle += dt;
 r.tPhase += dt;

 r.pmus = musclePressure(p, r.tCycle, period);

 // --- phase machine -------------------------------------------------------
 if (p.mode === 'psv') {
 // Patient-triggered, flow-cycled. The ventilator will not trigger again
 // until effort has fallen away and a fresh one begins, so cycling off in
 // the middle of an effort cannot immediately retrigger the same breath.
 if (r.pmus < 0.2) r.canTrigger = true;
 if (r.phase === 'exp' && r.canTrigger && r.pmus > 0.5) {
 r.phase = 'insp';
 r.tPhase = 0;
 r.peakInspFlow = 0;
 r.canTrigger = false;
 } else if (r.phase === 'insp') {
 r.peakInspFlow = Math.max(r.peakInspFlow, r.flow);
 if (r.flow < 0.25 * r.peakInspFlow && r.tPhase > 0.2) {
 r.phase = 'exp';
 r.tPhase = 0;
 }
 }
 } else if (p.mode === 'spont') {
 // Driven by the clock rather than by the muscle pressure, so the phase
 // cannot flicker at the two instants where effort passes through zero.
 r.phase = r.tCycle < neuralInspiratoryTime(p, period) ? 'insp' : 'exp';
 } else {
 if (r.phase === 'exp' && r.tCycle >= period) {
 r.phase = 'insp';
 r.tPhase = 0;
 r.tCycle = 0;
 } else if (r.phase === 'insp' && r.tPhase >= p.ti) {
 r.phase = 'exp';
 r.tPhase = 0;
 }
 }
 if (r.tCycle >= period && p.mode !== 'vcv' && p.mode !== 'pcv') r.tCycle = 0;

 // --- flow ----------------------------------------------------------------
 const palv = r.v / crs - r.pmus;
 const pao = airwayOpeningPressure(p, r, period);

 if (p.mode === 'vcv' && r.phase === 'insp') {
 // Constant inspiratory flow; airway pressure is whatever it takes.
 r.flow = p.vt / 1000 / p.ti;
 } else {
 const target = pao === null ? p.peep : pao;
 r.flow = (target - palv) / p.raw;
 }

 r.v = Math.max(0, r.v + r.flow * dt);
 if (r.flow > 0) r.vtAccum += r.flow * dt;

 // --- derived pressures ---------------------------------------------------
 const palvNew = r.v / crs - r.pmus;
 const ppl = PPL_FRC + r.v / ccw - r.pmus;
 const paw = p.mode === 'vcv' && r.phase === 'insp'
 ? palvNew + r.flow * p.raw
 : (pao === null ? p.peep : pao);

 r.palv = palvNew;
 r.ppl = ppl;
 r.paw = paw;
 r.pl = palvNew - ppl; // transpulmonary pressure
 r.lungVolume = p.frc + r.v; // absolute, L
 r.pab = p.pab0 + p.abdCoupling * r.v;

 // --- per-breath bookkeeping ----------------------------------------------
 r.pplMin = Math.min(r.pplMin, ppl);
 r.pplMax = Math.max(r.pplMax, ppl);
 r.ppeakAccum = Math.max(r.ppeakAccum, paw);
 // Static recoil pressure at end-inspiration, i.e. the plateau the ventilator
 // would show after an inspiratory hold.
 if (r.phase === 'insp') r.pplatCandidate = r.v / crs;

 // Everything reported per breath is latched exactly once, at the moment
 // inspiration ends — not on a time window that can fire twice.
 if (r.prevPhase === 'exp' && r.phase === 'insp') r.breathCount++;

 if (r.prevPhase === 'insp' && r.phase === 'exp') {
 r.lastPplat = r.pplatCandidate ?? 0;
 r.lastPpeak = r.ppeakAccum;
 r.lastPplSwing = r.pplMax - r.pplMin;
 r.lastVt = r.vtAccum * 1000;
 r.ppeakAccum = -Infinity;
 r.pplMin = ppl;
 r.pplMax = ppl;
 r.vtAccum = 0;
 }
 r.prevPhase = r.phase;

 // Intrinsic PEEP: alveolar pressure still above the set PEEP when the next
 // breath is about to be delivered.
 if (r.phase === 'exp' && r.tCycle > period * 0.95) {
 r.lastAutoPeep = Math.max(0, palvNew - p.peep);
 }

 return r;
}

// Pulmonary vascular resistance as a function of lung volume: the sum of an
// intra-alveolar term that rises with inflation and an extra-alveolar term that
// falls as the vessels are tethered open. Their sum is the J-shaped curve, with
// its nadir at FRC.
const K_ALV = 1.6;
const K_EXTRA = 2.4;
const F_ALV = 0.6;
const F_EXTRA = 0.4;

// The nadir of the J-curve sits at a *normal* functional residual capacity, not
// at whatever relaxation volume the diseased lung happens to have. A collapsed
// ARDS lung therefore operates on the left limb of the curve, where recruitment
// lowers PVR — the reason dropping PEEP in right ventricular failure can raise
// pulmonary vascular resistance instead of lowering it.
export const PVR_NADIR_VOLUME = 2.2; // L

export function pvrComponents(p, lungVolume) {
 const x = (lungVolume - PVR_NADIR_VOLUME) / PVR_NADIR_VOLUME;
 const alveolar = p.pvrBase * F_ALV * Math.exp(K_ALV * x);
 // Below FRC the extra-alveolar term is amplified by hypoxic vasoconstriction
 // acting on derecruited units.
 const hypoxic = 1 + p.hpv * 1.4 * Math.max(0, -x);
 const extraAlveolar = p.pvrBase * F_EXTRA * Math.exp(-K_EXTRA * x) * hypoxic;
 return { alveolar, extraAlveolar, total: alveolar + extraAlveolar, x };
}

export function pvrAt(p, lungVolume) {
 return clamp(pvrComponents(p, lungVolume).total, 0.005, 5);
}

import { defaultParams } from './parameters.js';
import {
 createRespiratoryState, stepRespiratory, respiratorySystemCompliance, pvrComponents,
} from './respiratory.js';
import {
 createCirculationState, stepCirculation, VASC, venousReturnBackPressure,
} from './circulation.js';
import { cmH2OtoMmHg, RESISTANCE_TO_DYN, RESISTANCE_TO_WOOD } from './units.js';

export const DEFAULT_DT = 0.00025; // 0.25 ms — small enough for the low valve resistances
const SAMPLE_HZ = 250;
export const TRACE_SECONDS = 12;
const TRACE_LEN = SAMPLE_HZ * TRACE_SECONDS;
const MEAN_TIME_CONSTANT = 3; // s, for the mean-pressure moving averages
const COMPARTMENTS = ['vSa', 'vSv', 'vRa', 'vRv', 'vPa', 'vPv', 'vLa', 'vLv'];
// The compartment volumes, compliances and resistances are calibrated for an
// adult of about this weight. It is stated because the validity condition for
// pulse pressure variation is expressed per kilogram.
const REFERENCE_WEIGHT_KG = 70;

class Ring {
 constructor(n) { this.buf = new Float32Array(n); this.n = n; this.i = 0; this.filled = 0; }
 push(v) { this.buf[this.i] = v; this.i = (this.i + 1) % this.n; if (this.filled < this.n) this.filled++; }
 // Oldest-to-newest into `out`; returns the count written.
 read(out) {
 const start = (this.i - this.filled + this.n) % this.n;
 for (let k = 0; k < this.filled; k++) out[k] = this.buf[(start + k) % this.n];
 return this.filled;
 }
}

const CHANNELS = ['paw', 'ppl', 'palv', 'art', 'cvp', 'pap', 'paop', 'flow', 'volume', 'co', 'insp'];

// The Guyton diagram is a steady-state analysis: its axes are mean pressure and
// mean flow. Cardiac pulsatility does not belong on it — right atrial pressure
// swings several mmHg every beat through its a, c and v waves, which is a third
// of the width of the plot — but the respiratory excursion is the whole point
// and must survive. A boxcar exactly one cardiac cycle long is the right filter:
// it nulls the cardiac fundamental completely while passing the much slower
// respiratory cycle almost untouched.
const CYCLE_HZ = 250;
const CYCLE_SECONDS = 2; // enough for a full cycle down to 30 beats/min

class CycleRing {
 constructor() {
 this.buf = new Float32Array(CYCLE_HZ * CYCLE_SECONDS);
 this.i = 0;
 this.filled = 0;
 }

 push(v) {
 this.buf[this.i] = v;
 this.i = (this.i + 1) % this.buf.length;
 if (this.filled < this.buf.length) this.filled++;
 }

 /** Mean of the most recent `samples` values. */
 mean(samples) {
 const n = Math.min(samples, this.filled);
 if (n < 1) return 0;
 let sum = 0;
 for (let k = 1; k <= n; k++) sum += this.buf[(this.i - k + this.buf.length) % this.buf.length];
 return sum / n;
 }
}

export class Simulator {
 /** `dt` is exposed so the convergence test can halve it. */
 constructor({ dt = DEFAULT_DT } = {}) {
 this.dt = dt;
 this.params = defaultParams();
 this.reset();
 }

 reset() {
 this.resp = createRespiratoryState();
 this.circ = createCirculationState(this.params);
 this.traces = {};
 this.scratch = {};
 for (const ch of CHANNELS) {
 this.traces[ch] = new Ring(TRACE_LEN);
 // One scratch buffer per channel, so a reader can hold on to the result
 // while reading another channel instead of having it overwritten.
 this.scratch[ch] = new Float32Array(TRACE_LEN);
 }
 this.time = 0;
 this.sampleAccum = 0;
 this.beatHistory = [];
 this.beatSeen = -1;
 this.sysRun = -1e9;
 this.diaRun = 1e9;
 this.papSysRun = -1e9;
 this.papDiaRun = 1e9;
 // Exponential moving averages over simulated time, so a mean pressure does
 // not depend on how the caller happens to chunk its calls to advance().
 this.ema = null;
 // Cycle-averaged quantities for the Guyton diagram.
 this.cycle = {
 ra: new CycleRing(), flow: new CycleRing(), pmsf: new CycleRing(),
 peri: new CycleRing(), ppl: new CycleRing(), pCrit: new CycleRing(),
 };
 this.cycleTick = 0;
 // Settle the model so the first frame the user sees is a steady state.
 this.advance(15, true);
 }

 /**
 * Changing stressed volume moves blood in or out of the venous reservoir —
 * a fluid bolus or a diuresis — rather than silently rescaling the model.
 */
 setParam(id, value) {
 if (id === 'stressedVolume') {
 this.circ.vSv += value - this.params.stressedVolume;
 }
 this.params[id] = value;
 if (id === 'frc') {
 // Keep end-expiratory volume physical when FRC moves.
 this.resp.v = Math.max(0, this.resp.v);
 }
 }

 /**
 * A scenario is a partial override of the defaults, so it has to be applied to
 * the defaults — not to whatever the previous scenario left behind. Otherwise
 * selecting a preset would give a different patient depending on which one you
 * looked at first.
 */
 applyScenario(scenario) {
 this.params = { ...defaultParams(), ...scenario.params };
 this.reset();
 }

 /** Advance simulated time by `seconds`, optionally without recording traces. */
 advance(seconds, silent = false) {
 const dt = this.dt;
 const steps = Math.min(Math.round(seconds / dt), 240000 * (DEFAULT_DT / dt));
 const sampleEvery = Math.max(1, Math.round(1 / (SAMPLE_HZ * dt)));
 for (let s = 0; s < steps; s++) {
 stepRespiratory(this.params, this.resp, dt);
 stepCirculation(this.params, this.circ, this.resp, dt);
 this.time += dt;
 this.accumulate();
 if (!silent && s % sampleEvery === 0) this.sample();
 }
 this.metrics = this.computeMetrics();
 }

 accumulate() {
 const c = this.circ;
 this.sysRun = Math.max(this.sysRun, c.p.sa);
 this.diaRun = Math.min(this.diaRun, c.p.sa);
 this.papSysRun = Math.max(this.papSysRun, c.p.pa);
 this.papDiaRun = Math.min(this.papDiaRun, c.p.pa);

 if (this.ema === null) {
 this.ema = { map: c.p.sa, cvp: c.p.ra, pap: c.p.pa, paop: c.p.la,
 ppl: c.p.ppl, peri: c.p.pPeri, pmsf: c.p.pmsf, pCrit: c.p.pCrit, flow: (c.q.vr * 60) / 1000 };
 } else {
 const alpha = this.dt / MEAN_TIME_CONSTANT;
 this.ema.map += alpha * (c.p.sa - this.ema.map);
 this.ema.cvp += alpha * (c.p.ra - this.ema.cvp);
 this.ema.pap += alpha * (c.p.pa - this.ema.pap);
 this.ema.paop += alpha * (c.p.la - this.ema.paop);
 this.ema.ppl += alpha * (c.p.ppl - this.ema.ppl);
 this.ema.peri += alpha * (c.p.pPeri - this.ema.peri);
 this.ema.pmsf += alpha * (c.p.pmsf - this.ema.pmsf);
 this.ema.pCrit += alpha * (c.p.pCrit - this.ema.pCrit);
 this.ema.flow += alpha * ((c.q.vr * 60) / 1000 - this.ema.flow);
 }

 if (this.cycleTick++ % Math.max(1, Math.round(1 / (CYCLE_HZ * this.dt))) === 0) {
 this.cycle.ra.push(c.p.ra);
 this.cycle.flow.push((c.q.vr * 60) / 1000);
 this.cycle.pmsf.push(c.p.pmsf);
 this.cycle.peri.push(c.p.pPeri);
 this.cycle.ppl.push(c.p.ppl);
 this.cycle.pCrit.push(c.p.pCrit);
 }

 if (c.beatCount !== this.beatSeen) {
 this.beatSeen = c.beatCount;
 this.beatHistory.push({
 t: this.time,
 pp: this.sysRun - this.diaRun,
 sv: c.sv,
 sbp: this.sysRun,
 dbp: this.diaRun,
 papSys: this.papSysRun,
 papDia: this.papDiaRun,
 });
 if (this.beatHistory.length > 40) this.beatHistory.shift();
 this.sysRun = -1e9; this.diaRun = 1e9;
 this.papSysRun = -1e9; this.papDiaRun = 1e9;
 }
 }

 sample() {
 const c = this.circ, r = this.resp;
 this.traces.paw.push(r.paw);
 this.traces.ppl.push(r.ppl);
 this.traces.palv.push(r.palv);
 this.traces.art.push(c.p.sa);
 this.traces.cvp.push(c.p.ra);
 this.traces.pap.push(c.p.pa);
 this.traces.paop.push(c.p.la);
 this.traces.flow.push(r.flow * 60); // L/min
 this.traces.volume.push((r.v * 1000)); // mL above FRC
 this.traces.co.push((c.q.av * 60) / 1000);
 this.traces.insp.push(r.flow > 0.002 ? 1 : 0);
 }

 trace(channel) {
 const buf = this.scratch[channel];
 const n = this.traces[channel].read(buf);
 return { data: buf, n };
 }

 computeMetrics() {
 const p = this.params, c = this.circ, r = this.resp;
 const hist = this.beatHistory;
 const period = 60 / p.rr;
 const recent = hist.filter((b) => b.t > this.time - period * 1.05);
 const pool = recent.length >= 2 ? recent : hist.slice(-4);

 let ppv = 0, svv = 0;
 if (pool.length >= 2) {
 const pps = pool.map((b) => b.pp);
 const svs = pool.map((b) => b.sv);
 const ppMax = Math.max(...pps), ppMin = Math.min(...pps);
 const svMax = Math.max(...svs), svMin = Math.min(...svs);
 ppv = ppMax + ppMin > 0 ? (200 * (ppMax - ppMin)) / (ppMax + ppMin) : 0;
 svv = svMax + svMin > 0 ? (200 * (svMax - svMin)) / (svMax + svMin) : 0;
 }

 const last = hist[hist.length - 1] ?? {};
 const ema = this.ema ?? {
 map: c.p.sa, cvp: c.p.ra, pap: c.p.pa, paop: c.p.la,
 ppl: c.p.ppl, peri: c.p.pPeri, pmsf: c.p.pmsf, pCrit: c.p.pCrit, flow: 0,
 };
 const { map, cvp, pap: papMean, paop } = ema;

 const co = (c.sv * p.hr) / 1000;
 const crs = respiratorySystemCompliance(p);
 const pvrComp = pvrComponents(p, r.lungVolume);

 // Whether each derived index can be read as the clinical quantity it shares
 // a name with. A dynamic index outside its validity conditions is not a
 // borderline result — it is not a result. See `interpretability` below.

 // Whether the numbers below mean anything at all. A model driven past the
 // range where its equations hold should say so rather than keep reporting
 // values in clinical units.
 const lvEf = c.lvEdv > 0 ? (100 * c.sv) / c.lvEdv : 0;
 const reasons = [];
 if (c.limitTicks > 0) reasons.push('a compartment was being drained faster than it could supply');
 const emptied = COMPARTMENTS.filter((k) => c[k] <= 1.5);
 if (emptied.length) reasons.push(`${emptied.join(', ')} at the volume floor`);
 if (!(lvEf >= 0 && lvEf <= 100)) reasons.push('ejection fraction outside 0–100%');
 if (!Number.isFinite(co) || !Number.isFinite(map)) reasons.push('non-finite result');

 // One cardiac cycle's worth of samples: the cardiac ripple averages out, the
 // respiratory swing survives.
 const window = Math.round((60 / p.hr) * CYCLE_HZ);
 const operatingPoint = {
 pra: this.cycle.ra.mean(window),
 flow: this.cycle.flow.mean(window),
 pmsf: this.cycle.pmsf.mean(window),
 pPeri: this.cycle.peri.mean(window),
 // The curves have to be evaluated on the same clock as the point. Left
 // instantaneous, they lead it by half a cardiac cycle, and the marker
 // drifts off them during the fast part of a breath.
 ppl: this.cycle.ppl.mean(window),
 pCrit: this.cycle.pCrit.mean(window),
 };

 const spontaneousEffort = p.mode === 'spont' || p.pmus > 0.5;
 const beatsPerBreath = p.hr / p.rr;

 // Conditions under which the dynamic indices stop meaning what their names
 // say. Levels: 'ok', 'caution', 'unavailable'.
 const ppvReasons = [];
 if (spontaneousEffort) ppvReasons.push('spontaneous effort — the index assumes a passive patient');
 if (r.lastVt < 8 * REFERENCE_WEIGHT_KG) ppvReasons.push(`tidal volume below 8 mL/kg (${REFERENCE_WEIGHT_KG} kg assumed)`);
 if (beatsPerBreath < 3.6) ppvReasons.push('fewer than 3.6 beats per breath');
 if (c.lvEdv > 0 && c.rvEdv / c.lvEdv > 1.2) ppvReasons.push('right ventricular dilatation — variation may reflect afterload, not preload');
 if (p.pab0 > 12) ppvReasons.push('raised intra-abdominal pressure');
 const ppvLevel = spontaneousEffort ? 'unavailable' : ppvReasons.length ? 'caution' : 'ok';

 const plateauLevel = spontaneousEffort ? 'unavailable' : 'ok';
 const wedgeLevel = c.p.zone3 >= 0.95 ? 'ok' : 'caution';
 const pvrDerivedLevel = co > 0.05 ? 'ok' : 'unavailable';

 // ESC/ERS 2022: pulmonary hypertension is mPAP above 20 mmHg; the
 // pre-capillary component additionally requires PVR above 2 Wood units with
 // a wedge of 15 mmHg or less.
 const pvrDerived = co > 0.05 ? (papMean - paop) / co : null;
 const phPresent = papMean > 20;
 const phClass = !phPresent ? null
 : (paop > 15 ? (pvrDerived !== null && pvrDerived > 2 ? 'combined' : 'post-capillary')
 : (pvrDerived !== null && pvrDerived > 2 ? 'pre-capillary' : 'unclassified'));

 const interpretability = {
 ppv: { level: ppvLevel, reasons: ppvReasons },
 plateau: { level: plateauLevel, reasons: plateauLevel === 'unavailable' ? ['no passive plateau during spontaneous effort'] : [] },
 wedge: {
 level: wedgeLevel,
 reasons: wedgeLevel === 'ok' ? []
 : ['left atrial pressure is only a wedge surrogate under West zone 3 conditions'],
 },
 pvrDerived: { level: pvrDerivedLevel, reasons: pvrDerivedLevel === 'ok' ? [] : ['no forward flow to divide by'] },
 };

 return {
 spontaneousEffort, beatsPerBreath, interpretability, phPresent, phClass,
 co, sv: c.sv, hr: p.hr,
 map, sbp: last.sbp ?? c.p.sa, dbp: last.dbp ?? c.p.sa,
 cvp, cvpTransmural: cvp - ema.ppl - ema.peri,
 papSys: last.papSys ?? c.p.pa, papDia: last.papDia ?? c.p.pa, papMean, paop,
 ppv, svv,
 valid: reasons.length === 0,
 invalidReasons: reasons,
 lvEdv: c.lvEdv, lvEsv: c.lvEsv, lvEf,
 rvEdv: c.rvEdv, rvEsv: c.rvEsv,
 rvLvRatio: c.lvEdv > 0 ? c.rvEdv / c.lvEdv : 1,
 pmsf: ema.pmsf, pCrit: ema.pCrit, pPeri: ema.peri, operatingPoint,
 // Same collapse law as the integrator, same averaging window as its terms.
 gradientVr: ema.pmsf - venousReturnBackPressure(cvp, ema.pCrit),
 ppl: r.ppl, palv: r.palv, paw: r.paw, pl: r.pl,
 lungVolume: r.lungVolume, pab: r.pab,
 pplat: r.lastPplat, ppeak: r.lastPpeak, autoPeep: r.lastAutoPeep,
 totalPeep: p.peep + r.lastAutoPeep,
 drivingPressure: r.lastPplat - (p.peep + r.lastAutoPeep),
 pplSwing: r.lastPplSwing,
 vtDelivered: r.lastVt,
 crs, expTimeConstant: (crs / 1000) * p.raw,
 pvr: c.p.pvr,
 // The J-curve coefficient the model integrates with. Not the same number a
 // clinician derives from a catheter, because the model also carries an
 // alveolar waterfall and zone conditions that the catheter formula folds
 // into its single resistance. Both are reported, separately named.
 pvrCoefficientWood: c.p.pvr * RESISTANCE_TO_WOOD,
 // null rather than NaN: at arrest there is no derivable resistance, and a
 // readout should say so instead of propagating a number that is not one.
 pvrDerivedWood: pvrDerived,
 pvrWood: c.p.pvr * RESISTANCE_TO_WOOD,
 pvrDyn: c.p.pvr * RESISTANCE_TO_DYN,
 svrDyn: p.svr * RESISTANCE_TO_DYN,
 pvrAlveolar: pvrComp.alveolar, pvrExtra: pvrComp.extraAlveolar,
 zone3: c.p.zone3,
 minuteVentilation: (r.lastVt * p.rr) / 1000,
 bloodVolume: COMPARTMENTS.reduce((t, k) => t + c[k], 0),
 minCompartment: Math.min(...COMPARTMENTS.map((k) => c[k])),
 stressedVenous: c.vSv - VASC.vuSv,
 };
 }
}

// Test suite. No dependencies, no framework:
//
// node tests/run.mjs
//
// It checks the things a physiological model can actually be held to — volume
// conservation, compartment positivity, convergence under time-step refinement,
// the direction of well-established relationships, and agreement between the
// integrator and the curves drawn from it — plus deterministic snapshots so
// that a change in behaviour has to be acknowledged rather than discovered.

import { Simulator, DEFAULT_DT } from '../src/model/simulator.js';
import { SCENARIOS } from '../src/model/scenarios.js';
import { PARAMETERS, defaultParams } from '../src/model/parameters.js';
import {
 venousReturnCurve, cardiacFunctionCurve, venousReturnFlow,
} from '../src/model/circulation.js';
import { pvrComponents, PVR_NADIR_VOLUME } from '../src/model/respiratory.js';
import { readFileSync } from 'node:fs';
import { SNAPSHOTS } from './snapshots.js';

// ---------------------------------------------------------------- harness ---

let passed = 0;
const failures = [];
let group = '';

const describe = (name) => { group = name; console.log(`\n${name}`); };

function check(name, condition, detail = '') {
 if (condition) {
 passed++;
 console.log(` pass ${name}`);
 } else {
 failures.push(`${group} / ${name}${detail ? ` — ${detail}` : ''}`);
 console.log(` FAIL ${name}${detail ? ` — ${detail}` : ''}`);
 }
}

const near = (a, b, tol) => Math.abs(a - b) <= tol;

function settled(overrides = {}, seconds = 30, opts = {}) {
 const s = new Simulator(opts);
 s.params = { ...defaultParams(), ...overrides };
 s.reset();
 s.advance(seconds, true);
 return s;
}

const COMPARTMENTS = ['vSa', 'vSv', 'vRa', 'vRv', 'vPa', 'vPv', 'vLa', 'vLv'];
const totalVolume = (c) => COMPARTMENTS.reduce((t, k) => t + c[k], 0);

// ------------------------------------------------------- volume conservation -

describe('Volume conservation');
for (const sc of SCENARIOS) {
 const s = new Simulator();
 s.applyScenario(sc);
 const before = totalVolume(s.circ);
 s.advance(40, true);
 const after = totalVolume(s.circ);
 check(sc.id, near(before, after, 0.01), `${before.toFixed(4)} -> ${after.toFixed(4)} mL`);
}

// ------------------------------------------------------------- positivity ----

describe('Compartment positivity across the scenarios');
for (const sc of SCENARIOS) {
 const s = new Simulator();
 s.applyScenario(sc);
 s.advance(40, true);
 const min = Math.min(...COMPARTMENTS.map((k) => s.circ[k]));
 check(sc.id, min > 0, `smallest compartment ${min.toFixed(2)} mL`);
}

// A deterministic sweep of the whole control space. The generator is a fixed
// linear congruential sequence, so a failure here is reproducible.
describe('Compartment positivity across a control-space sweep');
{
 let seed = 12345;
 const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
 let worstVolume = Infinity;
 let nonFinite = 0;
 let efOutOfRange = 0;
 let flagged = 0;
 const trials = 250;

 for (let i = 0; i < trials; i++) {
 const p = defaultParams();
 for (const spec of PARAMETERS) {
 p[spec.id] = spec.type === 'choice'
 ? spec.options[Math.floor(rnd() * spec.options.length)].value
 : spec.min + rnd() * (spec.max - spec.min);
 }
 const s = new Simulator();
 s.params = p;
 s.reset();
 s.advance(20, true);
 worstVolume = Math.min(worstVolume, Math.min(...COMPARTMENTS.map((k) => s.circ[k])));
 const m = s.metrics;
 for (const [, v] of Object.entries(m)) {
 if (typeof v === 'number' && !Number.isFinite(v)) nonFinite++;
 }
 if (!(m.lvEf >= 0 && m.lvEf <= 100)) efOutOfRange++;
 if (!m.valid) flagged++;
 }
 check(`${trials} configurations keep every compartment positive`, worstVolume > 0,
 `smallest volume ${worstVolume.toFixed(2)} mL`);
 check('no non-finite metric anywhere in the sweep', nonFinite === 0, `${nonFinite} found`);
 check('ejection fraction always within 0–100%', efOutOfRange === 0, `${efOutOfRange} outside`);
 check('states outside the model\'s range report themselves', flagged > 0,
 `${flagged} of ${trials} self-reported as not interpretable`);
}

// ------------------------------------------------------------- convergence ---

describe('Convergence under time-step refinement');
{
 // Measured on continuous quantities. Cardiac output is deliberately not used:
 // it is latched at a beat boundary, so which sample lands on the boundary
 // shifts with the step, and that is a sampling artefact rather than a
 // convergence failure.
 const runs = [0.0005, DEFAULT_DT, 0.000125].map((dt) => settled({}, 25, { dt }));
 const rel = (a, b) => Math.abs(a - b) / Math.abs(b);
 check('mean arterial pressure converges',
 rel(runs[0].metrics.map, runs[2].metrics.map) < 0.005,
 `${runs.map((r) => r.metrics.map.toFixed(3)).join(' -> ')} mmHg`);
 check('mean venous return converges',
 rel(runs[0].ema.flow, runs[2].ema.flow) < 0.01,
 `${runs.map((r) => r.ema.flow.toFixed(3)).join(' -> ')} L/min`);
 check('volume is conserved at every step size',
 runs.every((r) => near(totalVolume(r.circ), 5080, 0.01)),
 runs.map((r) => totalVolume(r.circ).toFixed(3)).join(' / '));
}

// -------------------------------------------------------------- determinism --

describe('Determinism');
{
 const a = settled({ peep: 9, hr: 88 }, 20);
 const b = settled({ peep: 9, hr: 88 }, 20);
 check('identical parameters give identical results',
 a.metrics.co === b.metrics.co && a.metrics.map === b.metrics.map,
 `${a.metrics.co} vs ${b.metrics.co}`);
}

// -------------------------------------------------- physiological relations --

describe('Physiological relations');
{
 const peep0 = settled({ peep: 0 });
 const peep16 = settled({ peep: 16 });
 check('PEEP raises central venous pressure',
 peep16.metrics.cvp > peep0.metrics.cvp,
 `${peep0.metrics.cvp.toFixed(1)} -> ${peep16.metrics.cvp.toFixed(1)} mmHg`);
 check('PEEP lowers cardiac output',
 peep16.metrics.co < peep0.metrics.co,
 `${peep0.metrics.co.toFixed(2)} -> ${peep16.metrics.co.toFixed(2)} L/min`);
 check('PEEP raises mean systemic filling pressure',
 peep16.metrics.pmsf > peep0.metrics.pmsf,
 `${peep0.metrics.pmsf.toFixed(1)} -> ${peep16.metrics.pmsf.toFixed(1)} mmHg`);

 const passive = settled({ mode: 'vcv', pmus: 0, peep: 0 });
 const spont = settled({ mode: 'spont', pmus: 8, peep: 0 });
 check('spontaneous breathing lowers measured central venous pressure',
 spont.metrics.cvp < passive.metrics.cvp,
 `${passive.metrics.cvp.toFixed(1)} -> ${spont.metrics.cvp.toFixed(1)} mmHg`);
 check('spontaneous breathing raises cardiac output',
 spont.metrics.co > passive.metrics.co,
 `${passive.metrics.co.toFixed(2)} -> ${spont.metrics.co.toFixed(2)} L/min`);
 check('transmural filling pressure exceeds the measured one when breathing in',
 spont.metrics.cvpTransmural > spont.metrics.cvp,
 `${spont.metrics.cvp.toFixed(1)} vs ${spont.metrics.cvpTransmural.toFixed(1)} mmHg`);

 const dry = settled({ stressedVolume: 330, vt: 560, ccw: 150, svr: 0.85, hr: 105 });
 const wet = settled({ stressedVolume: 830, vt: 560, ccw: 150, svr: 0.85, hr: 105 });
 check('hypovolaemia raises pulse pressure variation',
 dry.metrics.ppv > wet.metrics.ppv + 5,
 `${dry.metrics.ppv.toFixed(0)}% vs ${wet.metrics.ppv.toFixed(0)}%`);
 check('a fluid bolus raises cardiac output more when the patient is dry',
 wet.metrics.co - dry.metrics.co > 1.0,
 `${dry.metrics.co.toFixed(2)} -> ${wet.metrics.co.toFixed(2)} L/min`);

 const roomy = settled({ raw: 5, rr: 12, ti: 1.2 });
 const trapped = settled({ raw: 24, rr: 26, ti: 0.9, clung: 240, frc: 3.0 });
 check('a short expiratory time generates intrinsic PEEP',
 trapped.metrics.autoPeep > 2 && roomy.metrics.autoPeep < 0.5,
 `${roomy.metrics.autoPeep.toFixed(2)} vs ${trapped.metrics.autoPeep.toFixed(2)} cmH2O`);

 const softChest = settled({ ccw: 250, vt: 500 });
 const stiffChest = settled({ ccw: 70, vt: 500 });
 check('a stiff chest wall raises the pleural swing for the same tidal volume',
 stiffChest.metrics.pplSwing > softChest.metrics.pplSwing * 2,
 `${softChest.metrics.pplSwing.toFixed(1)} vs ${stiffChest.metrics.pplSwing.toFixed(1)} cmH2O`);

 const rvFail = settled({ eesRv: 0.22, pvrBase: 0.30 });
 check('right ventricular failure dilates the RV relative to the LV',
 rvFail.metrics.rvLvRatio > 1.4,
 `RV:LV ${rvFail.metrics.rvLvRatio.toFixed(2)}`);
 const noSeptum = settled({ eesRv: 0.22, pvrBase: 0.30, septal: 0 });
 check('removing septal coupling lets the left ventricle fill',
 noSeptum.metrics.lvEdv > rvFail.metrics.lvEdv,
 `${rvFail.metrics.lvEdv.toFixed(0)} -> ${noSeptum.metrics.lvEdv.toFixed(0)} mL`);
}

describe('The pulmonary vascular curve is J-shaped, not monotonic');
{
 const p = defaultParams();
 const at = (v) => pvrComponents(p, v).total;
 const nadir = at(PVR_NADIR_VOLUME);
 check('resistance rises below the nadir', at(1.2) > nadir * 1.2,
 `${at(1.2).toFixed(4)} vs ${nadir.toFixed(4)}`);
 check('resistance rises above the nadir', at(3.8) > nadir * 1.2,
 `${at(3.8).toFixed(4)} vs ${nadir.toFixed(4)}`);
 // Scan for the true minimum rather than assuming it.
 let best = { v: 0, r: Infinity };
 for (let v = 0.8; v <= 4.2; v += 0.01) { const r = at(v); if (r < best.r) best = { v, r }; }
 check('the minimum sits at a normal functional residual capacity',
 near(best.v, PVR_NADIR_VOLUME, 0.15), `minimum at ${best.v.toFixed(2)} L`);
}

// -------------------------------------------- integrator / drawing agreement -

describe('The drawn curves agree with the integrator');
for (const sc of SCENARIOS) {
 const s = new Simulator();
 s.applyScenario(sc);
 s.advance(30, true);
 const op = s.metrics.operatingPoint;
 const curve = venousReturnCurve(s.params, s.circ, op);
 // Read the curve at the simulated pressure and compare with the simulated flow.
 let drawn = NaN;
 const pts = curve.points;
 for (let i = 2; i < pts.length; i += 2) {
 const a = pts[i - 2], b = pts[i];
 if ((a <= op.pra && op.pra <= b) || (b <= op.pra && op.pra <= a)) {
 const t = (op.pra - a) / ((b - a) || 1);
 drawn = pts[i - 1] + t * (pts[i + 1] - pts[i - 1]);
 break;
 }
 }
 check(`${sc.id}: simulated state lies on the venous return curve`,
 Number.isFinite(drawn) && Math.abs(drawn - op.flow) < 0.45,
 `drawn ${drawn.toFixed(3)} vs simulated ${op.flow.toFixed(3)} L/min`);
}

describe('The venous return curve uses the integrator\'s own collapse law');
{
 const s = settled({});
 const op = s.metrics.operatingPoint;
 const direct = (venousReturnFlow(op.pmsf, op.pra, op.pCrit, s.circ.p.rvrEff) * 60) / 1000;
 const curve = venousReturnCurve(s.params, s.circ, op);
 let drawn = NaN;
 const pts = curve.points;
 for (let i = 2; i < pts.length; i += 2) {
 const a = pts[i - 2], b = pts[i];
 if ((a <= op.pra && op.pra <= b) || (b <= op.pra && op.pra <= a)) {
 const t = (op.pra - a) / ((b - a) || 1);
 drawn = pts[i - 1] + t * (pts[i + 1] - pts[i - 1]);
 break;
 }
 }
 check('curve and equation give the same flow', near(direct, drawn, 0.02),
 `${direct.toFixed(4)} vs ${drawn.toFixed(4)} L/min`);
}

// ---------------------------------------------------------------- snapshots --

describe('Scenario snapshots');
for (const sc of SCENARIOS) {
 const expected = SNAPSHOTS[sc.id];
 if (!expected) { check(sc.id, false, 'no snapshot recorded'); continue; }
 const s = new Simulator();
 s.applyScenario(sc);
 s.advance(30, true);
 const m = s.metrics;
 const got = { co: m.co, map: m.map, cvp: m.cvp, papMean: m.papMean, paop: m.paop, pvr: m.pvrCoefficientWood };
 const drift = Object.entries(expected)
 .filter(([k, v]) => Math.abs(got[k] - v) > Math.max(0.05, Math.abs(v) * 0.02))
 .map(([k, v]) => `${k} ${v} -> ${got[k].toFixed(2)}`);
 check(sc.id, drift.length === 0, drift.join(', '));
}

// ------------------------------------------------------- documentation drift --

// The README quotes what each scenario settles at. Rather than generate that
// table and lose the prose around it, check it: a number in the documentation
// that the model no longer produces is a defect, and this is how it gets found.
describe('The README scenario table matches the model');
{
 const readme = readFileSync(new URL('../README.md', import.meta.url), 'utf8');
 const section = readme.split('### What each one settles at')[1] ?? '';
 const rows = [...section.matchAll(/^\| ([^|]+?) \| ([\d.]+) \| (−?\d+) \| (−?[\d.]+) \|/gm)];
 check('the table was found and parsed', rows.length === SCENARIOS.length,
 `${rows.length} rows for ${SCENARIOS.length} scenarios`);

 for (const row of rows) {
 const [, name, co, map, cvp] = row;
 const sc = SCENARIOS.find((x) => x.name === name.trim());
 if (!sc) { check(`${name.trim()} is a real scenario`, false); continue; }
 const s = new Simulator();
 s.applyScenario(sc);
 s.advance(30, true);
 const m = s.metrics;
 const documented = { co: Number(co), map: Number(map), cvp: Number(cvp.replace('−', '-')) };
 const drift = [];
 if (!near(m.co, documented.co, 0.06)) drift.push(`CO ${documented.co} vs ${m.co.toFixed(2)}`);
 if (!near(m.map, documented.map, 1.5)) drift.push(`MAP ${documented.map} vs ${m.map.toFixed(0)}`);
 if (!near(m.cvp, documented.cvp, 0.3)) drift.push(`CVP ${documented.cvp} vs ${m.cvp.toFixed(1)}`);
 check(sc.name, drift.length === 0, drift.join(', '));
 }
}

// ------------------------------------------------------------------ summary --

console.log(`\n${passed} passed, ${failures.length} failed`);
if (failures.length) {
 console.log('\nFailures:');
 for (const f of failures) console.log(` - ${f}`);
 process.exit(1);
}

